    seen=set(); frames=[]
    for r in range(h):
        for c in range(w):
            color=g[r][c]
            if color==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            t,b=min(rs),max(rs); l,rr=min(cs),max(cs)
            if len(cells)==2*(b-t+1)+2*(rr-l+1)-4 and all(g[t][x]==color and g[b][x]==color for x in range(l,rr+1)) and all(g[y][l]==color and g[y][rr]==color for y in range(t,b+1)):
                frames.append((t,b,l,rr,color))
    frame_cells={(r,c) for t,b,l,rr,_ in frames for r in range(t,b+1) for c in range(l,rr+1)}
    counts=Counter(g[r][c] for r in range(h) for c in range(w) if g[r][c] not in (0,) and (r,c) not in frame_cells)
    for t,b,l,rr,_ in frames:
        it,ib,il,ir=t+1,b-1,l+1,rr-1
        if it>ib or il>ir: continue
        need=sum((r-it+c-il)%2==0 for r in range(it,ib+1) for c in range(il,ir+1))
        matches=[col for col,n in counts.items() if n==need]
        if len(matches)==1:
            col=matches[0]
            for r in range(it,ib+1):
                for c in range(il,ir+1):
                    if (r-it+c-il)%2==0: g[r][c]=col
    # Remove all isolated marker pixels, leaving only completed framed objects.
    for r in range(h):
        for c in range(w):
            if (r,c) not in frame_cells and g[r][c]!=0: g[r][c]=0
    return g
